;------------------------------------------------------------------------------
; 6187H - Basic command INIT dev[,"P"|"M"|"F"[,size]]
;   COM devices (3..5): INITCOM; devices 6.. go to the ROM modules (NOTHERE).
;   S1:/S2: (RAM module / slot RAM): re-format the slot. "P" program area, "M" RAM
;   disk of size (2..32 KB, F423H), "F" free; checks write protection (WPSLOT/WPCHK),
;   the running program (TITLE) and the slot status (SLOTSTAT), then builds the module
;   header (55H, ..., C5H) and moves the program descriptor.
; Work area F420H slot, F421H slot status, F422H mode index, F423H size, F424H saved S0DESC.
;------------------------------------------------------------------------------
K_INIT:
	call DEVNUM                     ; 6187  cd8062
	ret c                           ; 618A  d8
