;------------------------------------------------------------------------------
; 7E00H - Output / input statement dispatch
; The token table sends PRINT, INPUT, LPRINT and LLIST here (bank byte 06H),
; with HL at the operand. ROUTEIO (7E91H) looks at the operand and returns to
; its caller + C, i.e. into one of the JR slots following the CALL:
;   +0  normal (no '#', output not redirected)
;   +2  "#1".."#9"   file number
;   +4  "#-0"/"#-1"  or '#' + other with a kanji/ROM module that handles it (ROM4MAP
;                   b3, ROM6MAP b2)
;   +6  output redirected to COM (OPNDV 10H/11H and F14EH & B)
;   +8  "#" + anything else
; The slots end in NXTADR/INPUT1 (the P0-B0 statements, which handle '#' themselves via
; 4093H/4096H), in LPRINTB3B/LLISTB3B/COMINPUT, or in PASSROM (7E72H): the statement
; token (DE) is handed to the ROM modules through EXROMCOM, then continues with
; PRGEXE/DIRCOMEXE. Error 1BH: no module took it.
;------------------------------------------------------------------------------
K_PRINT:
	jr PRINTB3B                     ; 7E00  1809         keyword PRINT (F097H)
K_INPUT:
	jr INPUTB3B                     ; 7E02  1821         keyword INPUT (F091H)
K_LPRINT:
	jr LPRINTB                      ; 7E04  184c         keyword LPRINT (F0B9H)
K_LLIST:
	jr LLISTB                       ; 7E06  1856         keyword LLIST (F0B8H)
GOROM3BE:
	jp GOROM3BT                     ; 7E08  c3e87e       P0-B0 GOROM3B (COMM1500 b3): pass PRINT/other token F2CEH/F2CFH to the ROM modules
PRINTB3B:
	ld b,04H                        ; 7E0B  0604
